// SPDX-License-Identifier: GPL-3.0

pragma solidity =0.6.12;

import "./libraries/DoSwapLibrary.sol";
import "./libraries/DoSwapSafeMath.sol";
import "./libraries/TransferHelper.sol";
import "./interfaces/IDoSwapRouter.sol";
import "./interfaces/IDoSwapFactory.sol";
import "./interfaces/IDoSwapBEP20.sol";
import "./interfaces/IWDO.sol";
import "./interfaces/IRouterWhiteList.sol";
// import "hardhat/console.sol";
import "./libraries/Owner06.sol";

contract CASwapRouter is IDoSwapRouter, Ownable {
    using DoSwapSafeMath for uint256;

    address public immutable override factory;
    address public immutable override WDO;
    address public immutable routerWhiteListContract;

    modifier ensure(uint256 deadline) {
        require(deadline >= block.timestamp, "DoSwapRouter::ensure::EXPIRED");
        _;
    }

    constructor(address _factory, address _WDO, address _routerWhiteListContract) public {
        factory = _factory;
        WDO = _WDO;
        routerWhiteListContract = _routerWhiteListContract;
    }

    receive() external payable {
        assert(msg.sender == WDO); // only accept ETH via fallback from the WDO contract
    }

    modifier onlyLiquidityWhiteList() {
        require(_isLiquidityWhitelistedUser(msg.sender), " is not liquidity whitelisted");
        _;
    }

    function _isFeeWhitelistedUser(address user) public view returns (bool) {
        return IRouterWhiteList(routerWhiteListContract).isUserFeeWhitelisted(user);
    }

    function _isLiquidityWhitelistedUser(address user) public view returns (bool) {
        return IRouterWhiteList(routerWhiteListContract).isUserLiquidityWhitelisted(user);
    }


    // **** ADD LIQUIDITY ****
    function _addLiquidity(
        address tokenA,
        address tokenB,
        uint256 amountADesired,
        uint256 amountBDesired,
        uint256 amountAMin,
        uint256 amountBMin
    ) internal virtual returns (uint256 amountA, uint256 amountB) {
        // create the pair if it doesn't exist yet
        if (IDoSwapFactory(factory).getPair(tokenA, tokenB) == address(0)) {
            IDoSwapFactory(factory).createPair(tokenA, tokenB);
        }
        (uint256 reserveA, uint256 reserveB) = DoSwapLibrary.getReserves(factory, tokenA, tokenB);
        if (reserveA == 0 && reserveB == 0) {
            (amountA, amountB) = (amountADesired, amountBDesired);
        } else {
            uint256 amountBOptimal = DoSwapLibrary.quote(amountADesired, reserveA, reserveB);
            if (amountBOptimal <= amountBDesired) {
                require(amountBOptimal >= amountBMin, "DoSwapRouter::_addLiquidity::INSUFFICIENT_B_AMOUNT");
                (amountA, amountB) = (amountADesired, amountBOptimal);
            } else {
                uint256 amountAOptimal = DoSwapLibrary.quote(amountBDesired, reserveB, reserveA);
                assert(amountAOptimal <= amountADesired);
                require(amountAOptimal >= amountAMin, "DoSwapRouter::_addLiquidity::INSUFFICIENT_A_AMOUNT");
                (amountA, amountB) = (amountAOptimal, amountBDesired);
            }
        }
    }

    function addLiquidity(
        address tokenA,
        address tokenB,
        uint256 amountADesired,
        uint256 amountBDesired,
        uint256 amountAMin,
        uint256 amountBMin,
        address to,
        uint256 deadline
    )
    external
    virtual
    override onlyLiquidityWhiteList
    ensure(deadline)
    returns (
        uint256 amountA,
        uint256 amountB,
        uint256 liquidity
    )
    {
        (amountA, amountB) = _addLiquidity(tokenA, tokenB, amountADesired, amountBDesired, amountAMin, amountBMin);
        address pair = DoSwapLibrary.pairFor(factory, tokenA, tokenB);
        TransferHelper.safeTransferFrom(tokenA, msg.sender, pair, amountA);
        TransferHelper.safeTransferFrom(tokenB, msg.sender, pair, amountB);
        liquidity = IDoSwapPair(pair).mint(to);
        // return (0,0,0);
        return (amountA, amountB, liquidity);
    }

    function addLiquidityETH(
        address token,
        uint256 amountTokenDesired,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline
    )
    external
    payable
    virtual
    override onlyLiquidityWhiteList
    ensure(deadline)
    returns (
        uint256 amountToken,
        uint256 amountETH,
        uint256 liquidity
    )
    {
        (amountToken, amountETH) = _addLiquidity(token, WDO, amountTokenDesired, msg.value, amountTokenMin, amountETHMin);
        address pair = DoSwapLibrary.pairFor(factory, token, WDO);
        TransferHelper.safeTransferFrom(token, msg.sender, pair, amountToken);
        IWDO(WDO).deposit{ value: amountETH }();
        assert(IWDO(WDO).transfer(pair, amountETH));
        liquidity = IDoSwapPair(pair).mint(to);
        // refund dust eth, if any
        if (msg.value > amountETH) TransferHelper.safeTransferETH(msg.sender, msg.value - amountETH);
    }

    // **** REMOVE LIQUIDITY ****
    function removeLiquidity(
        address tokenA,
        address tokenB,
        uint256 liquidity,
        uint256 amountAMin,
        uint256 amountBMin,
        address to,
        uint256 deadline
    ) public virtual override onlyLiquidityWhiteList ensure(deadline) returns (uint256 amountA, uint256 amountB) {
        address pair = DoSwapLibrary.pairFor(factory, tokenA, tokenB);
        IDoSwapPair(pair).transferFrom(msg.sender, pair, liquidity); // send liquidity to pair
        (uint256 amount0, uint256 amount1) = IDoSwapPair(pair).burn(to);
        (address token0, ) = DoSwapLibrary.sortTokens(tokenA, tokenB);
        (amountA, amountB) = tokenA == token0 ? (amount0, amount1) : (amount1, amount0);
        require(amountA >= amountAMin, "DoSwapRouter::removeLiquidity::INSUFFICIENT_A_AMOUNT");
        require(amountB >= amountBMin, "DoSwapRouter::removeLiquidity::INSUFFICIENT_B_AMOUNT");
    }

    function removeLiquidityETH(
        address token,
        uint256 liquidity,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline
    ) public virtual override onlyLiquidityWhiteList ensure(deadline) returns (uint256 amountToken, uint256 amountETH) {
        (amountToken, amountETH) = removeLiquidity(
            token,
            WDO,
            liquidity,
            amountTokenMin,
            amountETHMin,
            address(this),
            deadline
        );
        TransferHelper.safeTransfer(token, to, amountToken);
        IWDO(WDO).withdraw(amountETH);
        TransferHelper.safeTransferETH(to, amountETH);
    }

    function removeLiquidityWithPermit(
        address tokenA,
        address tokenB,
        uint256 liquidity,
        uint256 amountAMin,
        uint256 amountBMin,
        address to,
        uint256 deadline,
        bool approveMax,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external virtual override onlyLiquidityWhiteList returns (uint256 amountA, uint256 amountB) {
        address pair = DoSwapLibrary.pairFor(factory, tokenA, tokenB);
        uint256 value = approveMax ? uint256(-1) : liquidity;
        IDoSwapPair(pair).permit(msg.sender, address(this), value, deadline, v, r, s);
        (amountA, amountB) = removeLiquidity(tokenA, tokenB, liquidity, amountAMin, amountBMin, to, deadline);
    }

    function removeLiquidityETHWithPermit(
        address token,
        uint256 liquidity,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline,
        bool approveMax,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external virtual override onlyLiquidityWhiteList returns (uint256 amountToken, uint256 amountETH) {
        address pair = DoSwapLibrary.pairFor(factory, token, WDO);
        uint256 value = approveMax ? uint256(-1) : liquidity;
        IDoSwapPair(pair).permit(msg.sender, address(this), value, deadline, v, r, s);
        (amountToken, amountETH) = removeLiquidityETH(token, liquidity, amountTokenMin, amountETHMin, to, deadline);
    }

    // **** REMOVE LIQUIDITY (supporting fee-on-transfer tokens) ****
    function removeLiquidityETHSupportingFeeOnTransferTokens(
        address token,
        uint256 liquidity,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline
    ) public virtual override onlyLiquidityWhiteList ensure(deadline) returns (uint256 amountETH) {
        (, amountETH) = removeLiquidity(token, WDO, liquidity, amountTokenMin, amountETHMin, address(this), deadline);
        TransferHelper.safeTransfer(token, to, IDoSwapBEP20(token).balanceOf(address(this)));
        IWDO(WDO).withdraw(amountETH);
        TransferHelper.safeTransferETH(to, amountETH);
    }

    function removeLiquidityETHWithPermitSupportingFeeOnTransferTokens(
        address token,
        uint256 liquidity,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline,
        bool approveMax,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external virtual override onlyLiquidityWhiteList  returns (uint256 amountETH) {
        address pair = DoSwapLibrary.pairFor(factory, token, WDO);
        uint256 value = approveMax ? uint256(-1) : liquidity;
        IDoSwapPair(pair).permit(msg.sender, address(this), value, deadline, v, r, s);
        amountETH = removeLiquidityETHSupportingFeeOnTransferTokens(
            token,
            liquidity,
            amountTokenMin,
            amountETHMin,
            to,
            deadline
        );
    }

    // **** SWAP ****
    // requires the initial amount to have already been sent to the first pair
    function _swap(
        uint256[] memory amounts,
        address[] memory path,
        address _to
    ) internal virtual {
        for (uint256 i; i < path.length - 1; i++) {
            (address input, address output) = (path[i], path[i + 1]);
            (address token0, ) = DoSwapLibrary.sortTokens(input, output);
            uint256 amountOut = amounts[i + 1];
            (uint256 amount0Out, uint256 amount1Out) = input == token0 ? (uint256(0), amountOut) : (amountOut, uint256(0));
            address to = i < path.length - 2 ? DoSwapLibrary.pairFor(factory, output, path[i + 2]) : _to;
            IDoSwapPair(DoSwapLibrary.pairFor(factory, input, output)).swap(amount0Out, amount1Out, to, new bytes(0));
        }
    }

    function swapExactTokensForTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external virtual override ensure(deadline) returns (uint256[] memory amounts) {
        // 根据手续费白名单状态选择计算方式
        if (_isFeeWhitelistedUser(msg.sender)) {
            amounts = DoSwapLibrary.getAmountsOutNoFee(factory, amountIn, path);
        } else {
            amounts = DoSwapLibrary.getAmountsOut(factory, amountIn, path);
        }

        require(
            amounts[amounts.length - 1] >= amountOutMin,
            "DoSwapRouter::swapExactTokensForTokens::INSUFFICIENT_OUTPUT_AMOUNT"
        );
        TransferHelper.safeTransferFrom(path[0], msg.sender, DoSwapLibrary.pairFor(factory, path[0], path[1]), amounts[0]);
        _swap(amounts, path, to);
    }

    function swapTokensForExactTokens(
        uint256 amountOut,
        uint256 amountInMax,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external virtual override ensure(deadline) returns (uint256[] memory amounts) {
        // 根据手续费白名单状态选择计算方式
        if (_isFeeWhitelistedUser(msg.sender)) {
            amounts = DoSwapLibrary.getAmountsInNoFee(factory, amountOut, path);
        } else {
            amounts = DoSwapLibrary.getAmountsIn(factory, amountOut, path);
        }

        require(amounts[0] <= amountInMax, "DoSwapRouter::swapTokensForExactTokens::EXCESSIVE_INPUT_AMOUNT");
        TransferHelper.safeTransferFrom(path[0], msg.sender, DoSwapLibrary.pairFor(factory, path[0], path[1]), amounts[0]);
        _swap(amounts, path, to);
    }

    function swapExactETHForTokens(
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external payable virtual override ensure(deadline) returns (uint256[] memory amounts) {
        require(path[0] == WDO, "DoSwapRouter::swapExactETHForTokens::INVALID_PATH");

        // 根据手续费白名单状态选择计算方式
        if (_isFeeWhitelistedUser(msg.sender)) {
            amounts = DoSwapLibrary.getAmountsOutNoFee(factory, msg.value, path);
        } else {
            amounts = DoSwapLibrary.getAmountsOut(factory, msg.value, path);
        }

        require(
            amounts[amounts.length - 1] >= amountOutMin,
            "DoSwapRouter::swapExactETHForTokens::INSUFFICIENT_OUTPUT_AMOUNT"
        );
        IWDO(WDO).deposit{ value: amounts[0] }();
        assert(IWDO(WDO).transfer(DoSwapLibrary.pairFor(factory, path[0], path[1]), amounts[0]));
        _swap(amounts, path, to);
    }

    function swapTokensForExactETH(
        uint256 amountOut,
        uint256 amountInMax,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external virtual override ensure(deadline) returns (uint256[] memory amounts) {
        require(path[path.length - 1] == WDO, "DoSwapRouter::swapTokensForExactETH::INVALID_PATH");

        // 根据手续费白名单状态选择计算方式
        if (_isFeeWhitelistedUser(msg.sender)) {
            amounts = DoSwapLibrary.getAmountsInNoFee(factory, amountOut, path);
        } else {
            amounts = DoSwapLibrary.getAmountsIn(factory, amountOut, path);
        }

        require(amounts[0] <= amountInMax, "DoSwapRouter::swapTokensForExactETH::EXCESSIVE_INPUT_AMOUNT");
        TransferHelper.safeTransferFrom(path[0], msg.sender, DoSwapLibrary.pairFor(factory, path[0], path[1]), amounts[0]);
        _swap(amounts, path, address(this));
        IWDO(WDO).withdraw(amounts[amounts.length - 1]);
        TransferHelper.safeTransferETH(to, amounts[amounts.length - 1]);
    }

    function swapExactTokensForETH(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external virtual override ensure(deadline) returns (uint256[] memory amounts) {
        require(path[path.length - 1] == WDO, "DoSwapRouter::swapExactTokensForETH::INVALID_PATH");

        // 根据手续费白名单状态选择计算方式
        if (_isFeeWhitelistedUser(msg.sender)) {
            amounts = DoSwapLibrary.getAmountsOutNoFee(factory, amountIn, path);
        } else {
            amounts = DoSwapLibrary.getAmountsOut(factory, amountIn, path);
        }

        require(
            amounts[amounts.length - 1] >= amountOutMin,
            "DoSwapRouter:swapExactTokensForETH::INSUFFICIENT_OUTPUT_AMOUNT"
        );
        TransferHelper.safeTransferFrom(path[0], msg.sender, DoSwapLibrary.pairFor(factory, path[0], path[1]), amounts[0]);
        _swap(amounts, path, address(this));
        IWDO(WDO).withdraw(amounts[amounts.length - 1]);
        TransferHelper.safeTransferETH(to, amounts[amounts.length - 1]);
    }

    function swapETHForExactTokens(
        uint256 amountOut,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external payable virtual override ensure(deadline) returns (uint256[] memory amounts) {
        require(path[0] == WDO, "DoSwapRouter::swapETHForExactTokens::INVALID_PATH");

        // 根据手续费白名单状态选择计算方式
        if (_isFeeWhitelistedUser(msg.sender)) {
            amounts = DoSwapLibrary.getAmountsInNoFee(factory, amountOut, path);
        } else {
            amounts = DoSwapLibrary.getAmountsIn(factory, amountOut, path);
        }

        require(amounts[0] <= msg.value, "DoSwapRouter::swapETHForExactTokens::EXCESSIVE_INPUT_AMOUNT");
        IWDO(WDO).deposit{ value: amounts[0] }();
        assert(IWDO(WDO).transfer(DoSwapLibrary.pairFor(factory, path[0], path[1]), amounts[0]));
        _swap(amounts, path, to);
        // refund dust eth, if any
        if (msg.value > amounts[0]) TransferHelper.safeTransferETH(msg.sender, msg.value - amounts[0]);
    }

    // **** SWAP (supporting fee-on-transfer tokens) ****
    // requires the initial amount to have already been sent to the first pair
    function _swapSupportingFeeOnTransferTokens(address[] memory path, address _to) internal virtual {
        for (uint256 i; i < path.length - 1; i++) {
            (address input, address output) = (path[i], path[i + 1]);
            (address token0, ) = DoSwapLibrary.sortTokens(input, output);
            IDoSwapPair pair = IDoSwapPair(DoSwapLibrary.pairFor(factory, input, output));
            uint256 amountInput;
            uint256 amountOutput;
            {
                // scope to avoid stack too deep errors
                (uint256 reserve0, uint256 reserve1, ) = pair.getReserves();
                (uint256 reserveInput, uint256 reserveOutput) = input == token0 ? (reserve0, reserve1) : (reserve1, reserve0);
                amountInput = IDoSwapBEP20(input).balanceOf(address(pair)).sub(reserveInput);
                amountOutput = DoSwapLibrary.getAmountOut(amountInput, reserveInput, reserveOutput, 0);
            }
            (uint256 amount0Out, uint256 amount1Out) = input == token0
                ? (uint256(0), amountOutput)
                : (amountOutput, uint256(0));
            address to = i < path.length - 2 ? DoSwapLibrary.pairFor(factory, output, path[i + 2]) : _to;
            pair.swap(amount0Out, amount1Out, to, new bytes(0));
        }
    }

    function swapExactTokensForTokensSupportingFeeOnTransferTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external virtual override ensure(deadline) {
        TransferHelper.safeTransferFrom(path[0], msg.sender, DoSwapLibrary.pairFor(factory, path[0], path[1]), amountIn);
        uint256 balanceBefore = IDoSwapBEP20(path[path.length - 1]).balanceOf(to);
        _swapSupportingFeeOnTransferTokens(path, to);
        require(
            IDoSwapBEP20(path[path.length - 1]).balanceOf(to).sub(balanceBefore) >= amountOutMin,
            "DoSwapRouter::swapExactTokensForTokensSupportingFeeOnTransferTokens::INSUFFICIENT_OUTPUT_AMOUNT"
        );
    }

    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external payable virtual override ensure(deadline) {
        require(path[0] == WDO, "DoSwapRouter::swapExactETHForTokensSupportingFeeOnTransferTokens::INVALID_PATH");
        uint256 amountIn = msg.value;
        IWDO(WDO).deposit{ value: amountIn }();
        assert(IWDO(WDO).transfer(DoSwapLibrary.pairFor(factory, path[0], path[1]), amountIn));
        uint256 balanceBefore = IDoSwapBEP20(path[path.length - 1]).balanceOf(to);
        _swapSupportingFeeOnTransferTokens(path, to);
        require(
            IDoSwapBEP20(path[path.length - 1]).balanceOf(to).sub(balanceBefore) >= amountOutMin,
            "DoSwapRouter::swapExactETHForTokensSupportingFeeOnTransferTokens::INSUFFICIENT_OUTPUT_AMOUNT"
        );
    }

    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external virtual override ensure(deadline) {
        require(
            path[path.length - 1] == WDO,
            "DoSwapRouter::swapExactTokensForETHSupportingFeeOnTransferTokens::INVALID_PATH"
        );
        TransferHelper.safeTransferFrom(path[0], msg.sender, DoSwapLibrary.pairFor(factory, path[0], path[1]), amountIn);
        _swapSupportingFeeOnTransferTokens(path, address(this));
        uint256 amountOut = IDoSwapBEP20(WDO).balanceOf(address(this));
        require(
            amountOut >= amountOutMin,
            "DoSwapRouter::swapExactTokensForETHSupportingFeeOnTransferTokens::INSUFFICIENT_OUTPUT_AMOUNT"
        );
        IWDO(WDO).withdraw(amountOut);
        TransferHelper.safeTransferETH(to, amountOut);
    }

    // **** LIBRARY FUNCTIONS ****
    function quote(
        uint256 amountA,
        uint256 reserveA,
        uint256 reserveB
    ) external pure virtual override returns (uint256 amountB) {
        return DoSwapLibrary.quote(amountA, reserveA, reserveB);
    }

    function getAmountOut(
        uint256 amountIn,
        uint256 reserveIn,
        uint256 reserveOut
    ) external pure virtual override returns (uint256 amountOut) {
        return DoSwapLibrary.getAmountOut(amountIn, reserveIn, reserveOut, 0);
    }

    function getAmountIn(
        uint256 amountOut,
        uint256 reserveIn,
        uint256 reserveOut
    ) external pure virtual override returns (uint256 amountIn) {
        return DoSwapLibrary.getAmountIn(amountOut, reserveIn, reserveOut, 0);
    }

    function getAmountsOut(uint256 amountIn, address[] memory path)
    external
    view
    virtual
    override
    returns (uint256[] memory amounts)
    {
        // 注意：这个函数无法访问 msg.sender，所以总是使用带手续费的版本
        // 实际的手续费白名单检查在具体的交易函数中进行
        return DoSwapLibrary.getAmountsOut(factory, amountIn, path);
    }

    function getAmountsIn(uint256 amountOut, address[] memory path)
    external
    view
    virtual
    override
    returns (uint256[] memory amounts)
    {
        // 注意：这个函数无法访问 msg.sender，所以总是使用带手续费的版本
        // 实际的手续费白名单检查在具体的交易函数中进行
        return DoSwapLibrary.getAmountsIn(factory, amountOut, path);
    }

    function pairCodeHash() external view returns (bytes32) {
        return IDoSwapFactory(factory).pairCodeHash();
    }
}

