pragma solidity >=0.5.0;

import "../interfaces/IDoSwapPair.sol";
import "../interfaces/IDoSwapFactory.sol";
import "./DoSwapSafeMath.sol";
//import "hardhat/console.sol";

library DoSwapLibrary {
  using DoSwapSafeMath for uint256;

  // returns sorted token addresses, used to handle return values from pairs sorted in this order
  function sortTokens(address tokenA, address tokenB) internal pure returns (address token0, address token1) {
    require(tokenA != tokenB, "DoSwapLibrary::sortTokens::IDENTICAL_ADDRESSES");
    (token0, token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
    require(token0 != address(0), "DoSwapLibrary::sortTokens::ZERO_ADDRESS");
  }

  // calculates the CREATE2 address for a pair without making any external calls
  function pairFor(
    address factory,
    address tokenA,
    address tokenB
  ) internal pure returns (address pair) {
    (address token0, address token1) = sortTokens(tokenA, tokenB);
    pair = address(
      uint256(
        keccak256(
          abi.encodePacked(
            hex"ff",
            factory,
            keccak256(abi.encodePacked(token0, token1)), // 0xf6027a86c6e83c065bb06f312cbb7abf961d71d57dd576386926f5f975a15511
            hex"90a575478e35a3814afce59815a43d73234ff267e6d57edb3f41abacedc933e7" // init code hash
          )
        )
      )
    );
  }

  // fetches and sorts the reserves for a pair
  function getReserves(
    address factory,
    address tokenA,
    address tokenB
  ) internal view returns (uint256 reserveA, uint256 reserveB) {
    (address token0, ) = sortTokens(tokenA, tokenB);
    address yyypair = pairFor(factory, tokenA, tokenB);
//   console.log("yyyyyy", yyypair);
    (uint256 reserve0, uint256 reserve1, ) = IDoSwapPair(pairFor(factory, tokenA, tokenB)).getReserves();
//   console.log("zzzzzz");
    (reserveA, reserveB) = tokenA == token0 ? (reserve0, reserve1) : (reserve1, reserve0);
  }

  // given some amount of an asset and pair reserves, returns an equivalent amount of the other asset
  function quote(
    uint256 amountA,
    uint256 reserveA,
    uint256 reserveB
  ) internal pure returns (uint256 amountB) {
    require(amountA > 0, "DoSwapLibrary::quote::INSUFFICIENT_AMOUNT");
    require(reserveA > 0 && reserveB > 0, "DoSwapLibrary::quote::INSUFFICIENT_LIQUIDITY");
    amountB = amountA.mul(reserveB) / reserveA;
  }

  // given an input amount of an asset and pair reserves, returns the maximum output amount of the other asset
  function getAmountOut(
    uint256 amountIn,
    uint256 reserveIn,
    uint256 reserveOut,
    uint256 feeBps // 手续费基点，如25表示0.25%
  ) internal pure returns (uint256 amountOut) {
    require(amountIn > 0, "DoSwapLibrary::getAmountOut::INSUFFICIENT_INPUT_AMOUNT");
    require(reserveIn > 0 && reserveOut > 0, "DoSwapLibrary::getAmountOut::INSUFFICIENT_LIQUIDITY");

    // 计算手续费和实际用于交易的金额
    uint256 feeAmount = amountIn.mul(feeBps) / 10000;
    uint256 amountInAfterFee = amountIn.sub(feeAmount);

    uint256 numerator = amountInAfterFee.mul(reserveOut);
    uint256 denominator = reserveIn.add(amountInAfterFee);
    amountOut = numerator / denominator;
  }

  // given an input amount of an asset and pair reserves, returns the maximum output amount of the other asset (no fee)
  function getAmountOutNoFee(
    uint256 amountIn,
    uint256 reserveIn,
    uint256 reserveOut
  ) internal pure returns (uint256 amountOut) {
    require(amountIn > 0, "DoSwapLibrary::getAmountOutNoFee::INSUFFICIENT_INPUT_AMOUNT");
    require(reserveIn > 0 && reserveOut > 0, "DoSwapLibrary::getAmountOutNoFee::INSUFFICIENT_LIQUIDITY");

    uint256 numerator = amountIn.mul(reserveOut);
    uint256 denominator = reserveIn.add(amountIn);
    amountOut = numerator / denominator;
  }

  // given an output amount of an asset and pair reserves, returns a required input amount of the other asset
  function getAmountIn(
    uint256 amountOut,
    uint256 reserveIn,
    uint256 reserveOut,
    uint256 feeBps // 手续费基点，如25表示0.25%
  ) internal pure returns (uint256 amountIn) {
    require(amountOut > 0, "DoSwapLibrary::getAmountIn::INSUFFICIENT_OUTPUT_AMOUNT");
    require(reserveIn > 0 && reserveOut > 0, "DoSwapLibrary::getAmountIn::INSUFFICIENT_LIQUIDITY");
    uint256 numerator = reserveIn.mul(amountOut).mul(10000);
    uint256 denominator = reserveOut.sub(amountOut).mul(10000- feeBps);
    // uint256 denominator = reserveOut.sub(amountOut).mul(9975);
    amountIn = (numerator / denominator).add(1);
  }

  // given an output amount of an asset and pair reserves, returns a required input amount of the other asset (no fee)
  function getAmountInNoFee(
    uint256 amountOut,
    uint256 reserveIn,
    uint256 reserveOut
  ) internal pure returns (uint256 amountIn) {
    require(amountOut > 0, "DoSwapLibrary::getAmountInNoFee::INSUFFICIENT_OUTPUT_AMOUNT");
    require(reserveIn > 0 && reserveOut > 0, "DoSwapLibrary::getAmountInNoFee::INSUFFICIENT_LIQUIDITY");
    uint256 numerator = reserveIn.mul(amountOut);
    uint256 denominator = reserveOut.sub(amountOut);
    amountIn = (numerator / denominator).add(1);
  }

  // performs chained getAmountOut calculations on any number of pairs
  function getAmountsOut(
    address factory,
    uint256 amountIn,
    address[] memory path
  ) internal view returns (uint256[] memory amounts) {
    require(path.length >= 2, "DoSwapLibrary::getAmountsOut::INVALID_PATH");
    amounts = new uint256[](path.length);
    amounts[0] = amountIn;
    for (uint256 i; i < path.length - 1; i++) {
      (uint256 reserveIn, uint256 reserveOut) = getReserves(factory, path[i], path[i + 1]);
      // 获取交易对的手续费
      uint256 feeBps = IDoSwapFactory(factory).getPairFeeBps(path[i], path[i + 1]);
      amounts[i + 1] = getAmountOut(amounts[i], reserveIn, reserveOut, feeBps);
    }
  }

  // performs chained getAmountOut calculations on any number of pairs (no fee)
  function getAmountsOutNoFee(
    address factory,
    uint256 amountIn,
    address[] memory path
  ) internal view returns (uint256[] memory amounts) {
    require(path.length >= 2, "DoSwapLibrary::getAmountsOutNoFee::INVALID_PATH");
    amounts = new uint256[](path.length);
    amounts[0] = amountIn;
    for (uint256 i; i < path.length - 1; i++) {
      (uint256 reserveIn, uint256 reserveOut) = getReserves(factory, path[i], path[i + 1]);
      amounts[i + 1] = getAmountOutNoFee(amounts[i], reserveIn, reserveOut);
    }
  }

  // performs chained getAmountIn calculations on any number of pairs
  function getAmountsIn(
    address factory,
    uint256 amountOut,
    address[] memory path
  ) internal view returns (uint256[] memory amounts) {
    require(path.length >= 2, "DoSwapLibrary::getAmountsIn::INVALID_PATH");
    amounts = new uint256[](path.length);
    amounts[amounts.length - 1] = amountOut;
    for (uint256 i = path.length - 1; i > 0; i--) {
      (uint256 reserveIn, uint256 reserveOut) = getReserves(factory, path[i - 1], path[i]);
      // 获取交易对的手续费
      uint256 feeBps = IDoSwapFactory(factory).getPairFeeBps(path[i - 1], path[i]);
      amounts[i - 1] = getAmountIn(amounts[i], reserveIn, reserveOut, feeBps);
    }
  }

  // performs chained getAmountIn calculations on any number of pairs (no fee)
  function getAmountsInNoFee(
    address factory,
    uint256 amountOut,
    address[] memory path
  ) internal view returns (uint256[] memory amounts) {
    require(path.length >= 2, "DoSwapLibrary::getAmountsInNoFee::INVALID_PATH");
    amounts = new uint256[](path.length);
    amounts[amounts.length - 1] = amountOut;
    for (uint256 i = path.length - 1; i > 0; i--) {
      (uint256 reserveIn, uint256 reserveOut) = getReserves(factory, path[i - 1], path[i]);
      amounts[i - 1] = getAmountInNoFee(amounts[i], reserveIn, reserveOut);
    }
  }
}

